import { Hono } from "hono";
const app = new Hono();
app.use("*", async (c, next) => {
  c.header("Access-Control-Allow-Origin", "*");
  c.header("Access-Control-Allow-Headers", "Content-Type, Authorization");
  if (c.req.method === "OPTIONS") return c.body(null, 204);
  await next();
});
app.get("/api/health", (c) => c.json({ ok: true, ts: Date.now() }));
app.get("/api/dashboard/stats", async (c) => {
  try {
    const db = c.env.DB;
    const [leads, orders, revenue, customers, groups] = await Promise.all([
      db.prepare("SELECT COUNT(*) c FROM leads").first(),
      db.prepare("SELECT COUNT(*) c FROM preorder_orders").first(),
      db.prepare("SELECT COALESCE(SUM(total_xaf),0) s FROM preorder_orders").first(),
      db.prepare("SELECT COUNT(*) c FROM customers").first(),
      db.prepare("SELECT COUNT(*) c FROM preorder_groups WHERE status='OPEN'").first()
    ]);
    return c.json({
      leads: leads?.c ?? 0,
      orders: orders?.c ?? 0,
      revenue: revenue?.s ?? 0,
      customers: customers?.c ?? 0,
      open_groups: groups?.c ?? 0
    });
  } catch (e) {
    return c.json({ leads: 0, orders: 0, revenue: 0, customers: 0, open_groups: 0, error: String(e?.message || e) });
  }
});
app.get("/api/services", async (c) => {
  try {
    const rows = await c.env.DB.prepare("SELECT * FROM services").all();
    return c.json(rows.results);
  } catch {
    return c.json([]);
  }
});
app.get("/api/products", async (c) => {
  try {
    const rows = await c.env.DB.prepare("SELECT * FROM products LIMIT 200").all();
    return c.json(rows.results);
  } catch {
    return c.json([]);
  }
});
app.get("/api/groups", async (c) => {
  try {
    const rows = await c.env.DB.prepare("SELECT * FROM preorder_groups ORDER BY id DESC").all();
    return c.json(rows.results);
  } catch {
    return c.json([]);
  }
});
const fallback = ({ request, platform }) => app.fetch(request, platform.env);
const GET = fallback;
const POST = fallback;
const PUT = fallback;
const DELETE = fallback;
const PATCH = fallback;
export {
  DELETE,
  GET,
  PATCH,
  POST,
  PUT,
  fallback
};
